 select 'IF NOT EXISTS(SELECT 1 FROM _tdaumajor WHERE '+'MajorSeq	='+CONVERT(VARCHAR(30), ISNULL(MajorSeq, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+ 'INSERT _TDAUMajor(CompanySeq, MajorSeq, MajorName, MajorSort, SMInputMethod, Remark, WordSeq, FixCombo, IsCombo, LastUserSeq, LastDateTime, AddCheckScript, AddSaveScript, CustSeq, DevMode, IsUse, IsMinorNo) '+CHAR(13)+ + 'SELECT '+ CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.MajorSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.MajorSeq) END + ',' + CASE WHEN A.MajorName IS NULL THEN N'NULL' ELSE 'N''' + (A.MajorName) + '''' END + ',' + CASE WHEN A.MajorSort IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.MajorSort) END + ',' + CASE WHEN A.SMInputMethod IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.SMInputMethod) END + ',' + CASE WHEN A.Remark IS NULL THEN N'NULL' ELSE 'N''' + (A.Remark) + '''' END + ',' + CASE WHEN A.WordSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.WordSeq) END + ',' + CASE WHEN A.FixCombo IS NULL THEN N'NULL' ELSE 'N''' + (A.FixCombo) + '''' END + ',' + CASE WHEN A.IsCombo IS NULL THEN N'NULL' ELSE 'N''' + (A.IsCombo) + '''' END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.AddCheckScript IS NULL THEN N'NULL' ELSE 'N''' + (A.AddCheckScript) + '''' END + ',' + CASE WHEN A.AddSaveScript IS NULL THEN N'NULL' ELSE 'N''' + (A.AddSaveScript) + '''' END + ',' + CASE WHEN A.CustSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.CustSeq) END + ',' + CASE WHEN A.DevMode IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DevMode) END + ',' + CASE WHEN A.IsUse IS NULL THEN N'NULL' ELSE 'N''' + (A.IsUse) + '''' END + ',' + CASE WHEN A.IsMinorNo IS NULL THEN N'NULL' ELSE 'N''' + (A.IsMinorNo) + '''' END +' FROM _TCACOMPANY'+CHAR(13)+' end' FROM _TDAUMajor AS A WITH(NOLOCK) 
   join #Temp_Seq as b on type =2 and CodeHelpParams = a.majorseq
 union all 
 select 'IF NOT EXISTS(SELECT 1 FROM _tdauminor WHERE '+'MinorSeq	='+CONVERT(VARCHAR(30), ISNULL(MinorSeq, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+ 'INSERT _TDAUMinor(CompanySeq, MinorSeq, MajorSeq, MinorName, MinorSort, Remark, WordSeq, LastUserSeq, LastDateTime, IsUse, MinorNo) '+CHAR(13)+ + 'SELECT '+ CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.MinorSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.MinorSeq) END + ',' + CASE WHEN A.MajorSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.MajorSeq) END + ',' + CASE WHEN A.MinorName IS NULL THEN N'NULL' ELSE 'N''' + (A.MinorName) + '''' END + ',' + CASE WHEN A.MinorSort IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.MinorSort) END + ',' + CASE WHEN A.Remark IS NULL THEN N'NULL' ELSE 'N''' + (A.Remark) + '''' END + ',' + CASE WHEN A.WordSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.WordSeq) END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.IsUse IS NULL THEN N'NULL' ELSE 'N''' + (A.IsUse) + '''' END + ',' + CASE WHEN A.MinorNo IS NULL THEN N'NULL' ELSE 'N''' + (A.MinorNo) + '''' END +' FROM _TCACOMPANY'+CHAR(13)+' end' FROM _TDAUMinor AS A WITH(NOLOCK) 
    join #Temp_Seq as b on type =2 and CodeHelpParams = a.majorseq

 union all 
 select 'IF NOT EXISTS(SELECT 1 FROM _tcomuserdefine WHERE '+'TableName	='+''''+CONVERT(VARCHAR(30), ISNULL(TableName, 0))+''''+' AND '+'TitleSerl	='+CONVERT(VARCHAR(30), ISNULL(TitleSerl, 0))+' AND '+'DefineUnitSeq	='+CONVERT(VARCHAR(30), ISNULL(DefineUnitSeq, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+ 'INSERT _TCOMUserDefine(CompanySeq, TableName, DefineUnitSeq, TitleSerl, Title, IsEss, CodeHelpConst, CodeHelpParams, SMInputType, MaskAndCaption, QrySort, IsFix, DataFieldID, IsCodeHelpTitle, LastUserSeq, LastDateTime, DecLen, WordSeq) '+CHAR(13)+ + 'SELECT '+ CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.TableName IS NULL THEN N'NULL' ELSE 'N''' + (A.TableName) + '''' END + ',' + CASE WHEN A.DefineUnitSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DefineUnitSeq) END + ',' + CASE WHEN A.TitleSerl IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.TitleSerl) END + ',' + CASE WHEN A.Title IS NULL THEN N'NULL' ELSE 'N''' + (A.Title) + '''' END + ',' + CASE WHEN A.IsEss IS NULL THEN N'NULL' ELSE 'N''' + (A.IsEss) + '''' END + ',' + CASE WHEN A.CodeHelpConst IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.CodeHelpConst) END + ',' + CASE WHEN A.CodeHelpParams IS NULL THEN N'NULL' ELSE 'N''' + (A.CodeHelpParams) + '''' END + ',' + CASE WHEN A.SMInputType IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.SMInputType) END + ',' + CASE WHEN A.MaskAndCaption IS NULL THEN N'NULL' ELSE 'N''' + (A.MaskAndCaption) + '''' END + ',' + CASE WHEN A.QrySort IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.QrySort) END + ',' + CASE WHEN A.IsFix IS NULL THEN N'NULL' ELSE 'N''' + (A.IsFix) + '''' END + ',' + CASE WHEN A.DataFieldID IS NULL THEN N'NULL' ELSE 'N''' + (A.DataFieldID) + '''' END + ',' + CASE WHEN A.IsCodeHelpTitle IS NULL THEN N'NULL' ELSE 'N''' + (A.IsCodeHelpTitle) + '''' END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.DecLen IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DecLen) END + ',' + CASE WHEN A.WordSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.WordSeq) END +' FROM _TCACOMPANY'+CHAR(13)+' end' FROM _TCOMUserDefine AS A WITH(NOLOCK) 
